get.description:
Get current CPU statistics for all plugins.

Returns:
    {
        "plugins": [
            {
                "uri": str,
                "name": str,
                "call_count": int,
                "avg_time_us": float,
                "max_time_us": float,
                "cpu_percent": float,
                "calls_per_second": float
            },
            ...
        ],
        "chain": {
            "total_plugins": int,
            "total_cpu_percent": float,
            "total_avg_us": float,
            "total_max_us": float,
            "deadline_us": float,
            "utilization_percent": float
        },
        "profiler": {
            "sample_rate": int,
            "buffer_size": int,
            "deadline_us": float,
            "overhead_per_call_us": float
        }
    }

put.description:
Update reverb parameters.

Args:
    request: Parameter update request

Returns:
    {
        "status": "ok",
        "parameters": {...}
    }

post.description:
Toggle reverb bypass.

Returns:
    {
        "status": "ok",
        "bypass": bool
    }

Reset reverb engine (clear buffers).

Returns:
    {
        "status": "ok",
        "message": str
    }

Upload custom IR file.

Args:
    file: Uploaded WAV/FLAC file

Returns:
    {
        "status": "ok",
        "file_path": str,
        "metadata": {...}
    }

get.description:
Get IR category tree.

Returns:
    {
        "categories": [...],
        "count": int
    }

Get available IR libraries.

Returns:
    {
        "libraries": [
            {
                "name": str,
                "count": int,
                "license": str
            },
            ...
        ]
    }

Get current download status.

Returns:
    {
        "is_downloading": bool,
        "progress_percent": float,
        "stats": {...}
    }

post.description:
Cancel ongoing download.

Returns:
    {
        "status": "cancelled"
    }

Pause ongoing download.

Returns:
    {
        "status": "paused"
    }

Resume paused download.

Returns:
    {
        "status": "resumed"
    }

Reset download stats and prepare for a new download.

Returns:
    {
        "status": "reset"
    }

get.description:
Get current folder statistics.

Returns:
    {
        "nams": {...},
        "irs": {...},
        "lv2": {...}
    }

Get current scan status.

Returns:
    {
        "scanning": bool,
        "message": str
    }

Get network share (SMB) status and accessibility info.

Returns:
    {
        "smb_enabled": bool,
        "smb_port_445": bool,
        "smb_port_139": bool,
        "local_ip": str,
        "shares": [{"name": str, "path": str, "accessible": bool}],
        "access_urls": {"windows": str, "linux": str, "mac": str}
    }

Get counts of all audio assets (NAMs, IRs, LV2 plugins).

Returns:
    {
        "nams": int,
        "irs": {"total": int, "cabinets": int, "reverbs": int},
        "lv2": {"system": int, "user": int, "total": int}
    }

post.description:
Compatibility endpoint for frontend bulk apply.

Accepts:
  {"cores": [{"core_id": ..., "services": [...], "priority": "...", "isolated": ...}, ...]}

get.description:
Get real-time CPU metrics relevant to audio latency.

Returns:
    {
        "cpu_load": {...},
        "frequency": {...},
        "temperature": {...},
        "process_stats": {...}
    }

Get all plugin priorities.

Returns:
    {
        "priorities": [
            {
                "uri": str,
                "priority": int,
                "estimated_cpu_us": float,
                "auto_bypass": bool,
                "status": str
            },
            ...
        ]
    }

List all snapshots and current snapshot ID

Returns:
    {
        "snapshots": [SnapshotInfo, ...],
        "current": int
    }

Get available SoundFont libraries (sources for downloading).

Returns:
    {
        "libraries": [
            {
                "name": str,
                "displayName": str,
                "description": str,
                "license": str,
                "count": int,
                "iconColor": str
            },
            ...
        ]
    }

Get SoundFont categories.

Returns:
    {
        "categories": [
            {"name": str, "count": int},
            ...
        ]
    }

Get current download status.

Returns:
    {
        "is_downloading": bool,
        "progress_percent": float,
        "stats": {...}
    }

